S=/private/tmp/claude-501/-Users-maximiliansmidt-RustroverProjects-family-tree/f3b54c46-7e5d-4f97-883a-a3a056f0e27c/scratchpad; cat > $S/repro.mjs <<'EOF'
import { chromium } from "/Users/maximiliansmidt/RustroverProjects/family-tree/e2e/node_modules/playwright/index.mjs";
const BASE = process.argv[2] || "http://localhost:8080";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
await page.route("**/api/users/me/preferences/tutorial", (r) => r.request().method() === "GET" ? r.fulfill({ json: { completed: true } }) : r.continue());
await page.route("**/api/sse/events*", (r) => r.abort());
const logs = [];
page.on("console", (m) => { if (["warning","error"].includes(m.type())) logs.push(m.type()+": "+m.text().slice(0,200)); });
await page.goto(BASE);
await page.getByLabel(/Benutzername|Username/).fill("e2e-admin");
await page.getByLabel(/Passwort|Password/).fill("e2e-admin-password");
await page.keyboard.press("Enter");
await page.waitForSelector(".react-flow__node-familyMember", { timeout: 20000 });
await page.waitForTimeout(1500);
const snap = async (label) => {
  const edges = await page.$$eval(".react-flow__edge", (els) => els.map((e) => e.getAttribute("data-id")));
  const nodes = await page.$$eval(".react-flow__node", (els) => els.map((e) => (e.getAttribute("data-id")||"").slice(0,8) + "@" + e.style.transform));
  console.log(label, "edges:", edges.length, JSON.stringify(edges.map(e=>e.replace(/[0-9a-f-]{36}/g, m=>m.slice(0,4)))));
};
await snap("initial");
const node = (name) => page.locator(".react-flow__node-familyMember", { hasText: name });
const box = async (n) => await node(n).boundingBox();
const drag = async (name, dx, dy = 0) => {
  const b = await box(name);
  const x = b.x + 30, y = b.y + b.height / 2;
  await page.mouse.move(x, y); await page.mouse.down();
  for (let i = 1; i <= 20; i++) await page.mouse.move(x + dx * i / 20, y + dy * i / 20);
  await page.mouse.up();
};
const mode = process.argv[3] || "flip";
if (mode === "control") { await drag("Alice", -40, 40); }
else {
  const a = await box("Alice"), b = await box("Bob");
  await drag("Alice", (b.x - a.x) + b.width + 60, 40);
}
await page.waitForTimeout(300); await snap("just after drop");
await page.waitForTimeout(3000); await snap("after save+derive");
await page.screenshot({ path: process.env.SHOT || "/tmp/x.png" });
console.log(logs.join("\n"));
await browser.close();
EOF
cd $S && SHOT=$S/redesign-flip.png node repro.mjs http://localhost:8080 flip

